Item.method_code:
const dialogHandler = (dialogResult, actionType) => {
	if (actionType === 'doubleclick') {
		addItemTypes(dialogResult);
		return false;
	}

	return true;
};

const addItemTypes = async (selectedItemTypes = []) => {
	if (selectedItemTypes.length === 0) {
		return;
	}
	const itemTypesIds = Array.isArray(selectedItemTypes) ? selectedItemTypes : [selectedItemTypes.itemID];

	const { getActions, getState } = options;
	const actions = getActions();
	const { defaultLanguageCode, languages } = getState();
	const defaultItemTypeIcon = '../images/DefaultItemType.svg';
	const adminRole = {
		id: '2618D6F5A90949BAA7E920D1B04C7EE1',
		keyedName: 'Administrators'
	};
	let multilingualLabelsPromise;
	const relatedItemsIds = new Map();

	const promises = itemTypesIds.map(async (itemTypeId) => {
		const itemType = await ArasModules.metadata.itemType.getItemType(
			itemTypeId,
			'id'
		);

		const label = itemType['label_plural'] || itemType['name'];
		const relatedItemProps = {
			label,
			[`label@aras.lang.${defaultLanguageCode}`]: label,
			image: itemType['open_icon'] || defaultItemTypeIcon,
			additional_data: { itemTypeId }
		};
		const relatedItem = actions.addRelatedItem(relatedItemProps);
		relatedItemsIds.set(itemTypeId, relatedItem.id);

		const relationshipItemProps = {
			related_id: relatedItem.id,
			'role@aras.id': adminRole.id,
			'role@aras.keyed_name': adminRole.keyedName
		};
		const relationshipItem = actions.addRelationshipItem(relationshipItemProps);

		return relationshipItem;
	});

	if (languages?.length > 1) {
		const idsFilter = itemTypesIds.map((id) => `id eq '${id}'`).join(' or ');
		const odataFilter = `(${idsFilter})`;
		const requestUrl = `ItemType?$select=label_plural,id&lang=*&$filter=${odataFilter}`;
		multilingualLabelsPromise = ArasModules.odataFetch(requestUrl);
	}

	const addedRelationshipItems = await Promise.all(promises);
	const selectAddedItem = addedRelationshipItems.length === 1;
	if (selectAddedItem) {
		const { id } = addedRelationshipItems[0];
		actions.selectItem(id);
	}

	const labelsData = await multilingualLabelsPromise;

	if (!labelsData?.value) {
		return;
	}

	labelsData.value.forEach((itemType) => {
		const multilingualLabels = languages.reduce((accum, { code }) => {
			const langPropName = `label@aras.lang.${code}`;
			const langValueName = `label_plural@aras.lang.${code}`;
			if (itemType[langValueName]) {
				accum[langPropName] = itemType[langValueName];
			}

			return accum;
		}, {});

		if (Object.keys(multilingualLabels).length === 0) {
			return;
		}

		actions.editItem(relatedItemsIds.get(itemType.id), multilingualLabels);
	});
};

const dialogParams = {
	type: 'SearchDialog',
	itemtypeName: 'ItemType',
	multiselect: true,
	handler: dialogHandler
};

const itemTypesIds = await ArasModules.MaximazableDialog.show(
	'iframe',
	dialogParams
).promise;

await addItemTypes(itemTypesIds);
